cat > /tmp/rev8/impl.mjs <<'EOF'
import crypto from 'node:crypto';
const SHORT = {8:'\\b',9:'\\t',10:'\\n',12:'\\f',13:'\\r',34:'\\"',92:'\\\\'};
function esc(s){let o='';for(let i=0;i<s.length;i++){const c=s.charCodeAt(i);
 if(SHORT[c]!==undefined){o+=SHORT[c];}
 else if(c>=0x20&&c<=0x7e){o+=s[i];}
 else{o+='\\u'+c.toString(16).padStart(4,'0');}}
 return o;}
function b64url(buf){return Buffer.from(buf).toString('base64').replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
const payload=process.argv[2], secret=process.argv[3];
const hdr='{"alg":"HS256","typ":"JWT"}';
const pl='{"data":"'+esc(payload)+'"}';
const si=b64url(Buffer.from(hdr,'utf8'))+'.'+b64url(Buffer.from(pl,'utf8'));
const sig=b64url(crypto.createHmac('sha256',Buffer.from(secret,'utf8')).update(si,'ascii').digest());
process.stdout.write(si+'.'+sig);
EOF
cd /tmp/rev8; fail=0; tot=0
tests=( "hello|s3cret" "|" "a\"b\\c/d|k" "<>&'\`|k" "héllo wörld|sec" "中文测试|sec" "😀|sec" "aé中😀z|sec" "~~~|k" "???|k" "x y|k" "tab	end|k" "ÿÿ|k" "…|k" )
for t in "${tests[@]}"; do pl="${t%%|*}"; sc="${t#*|}"; a=$(/workspace/dataset/test8_executable --payload "$pl" --secret "$sc" 2>/dev/null | head -1); b=$(node /tmp/rev8/impl.mjs "$pl" "$sc"); tot=$((tot+1)); if [ "$a" = "$b" ]; then echo "OK   [$pl]"; else fail=$((fail+1)); echo "DIFF [$pl]"; echo "  exe=$a"; echo "  js =$b"; fi; done
echo "total=$tot fail=$fail"

cd /tmp/rev8; node -e '
const cps=[];
for(let i=1;i<128;i++)cps.push(i);
const extra=[0x80,0x9f,0xa0,0xe9,0xff,0x100,0x2028,0x2029,0x3042,0x4e2d,0xd7ff,0xe000,0xfeff,0xffff,0x10000,0x1f600,0x10ffff];
extra.forEach(c=>cps.push(c));
let out=[];
let rnd=12345; const nx=()=>{rnd=(rnd*1103515245+12345)>>>0; return rnd;};
for(let t=0;t<120;t++){let s="";const n=1+nx()%6;for(let j=0;j<n;j++){s+=String.fromCodePoint(cps[nx()%cps.length]);}out.push(s);}
require("fs").writeFileSync("/tmp/rev8/cases.json",JSON.stringify(out));
console.log("wrote",out.length);'
node -e '
const {execFileSync}=require("child_process");
const cases=JSON.parse(require("fs").readFileSync("/tmp/rev8/cases.json","utf8"));
let fail=0,shown=0;
for(const c of cases){
 const sec="s"+c.length;
 let a;try{a=execFileSync("/workspace/dataset/test8_executable",["--payload",c,"--secret",sec],{encoding:"utf8"}).split("\n")[0];}catch(e){a="ERR:"+e.status;}
 const b=execFileSync("node",["/tmp/rev8/impl.mjs",c,sec],{encoding:"utf8"});
 if(a!==b){fail++;if(shown++<10)console.log("DIFF",JSON.stringify(c),"\n exe="+a,"\n js ="+b);}
}
console.log("total="+cases.length,"fail="+fail);'

